UNITS = [{'id': 'PEDS-U337', 'ch': 42, 'n': 1, 'title': 'Spinal Muscular Atrophy — Genetics & Clinical Features', 'sec': 'SMA genetics and features · p194', 'qs': ['PEDS-C42-001', 'PEDS-C42-002', 'PEDS-C42-003', 'PEDS-C42-004', 'PEDS-C42-005', 'PEDS-C42-006', 'PEDS-C42-007', 'PEDS-C42-008', 'PEDS-C42-009', 'PEDS-C42-010', 'PEDS-C42-011', 'PEDS-C42-012', 'PEDS-C42-013', 'PEDS-C42-014', 'PEDS-C42-015', 'PEDS-C42-016', 'PEDS-C42-017', 'PEDS-C42-018', 'PEDS-C42-019', 'PEDS-C42-020', 'PEDS-C42-021', 'PEDS-C42-022', 'PEDS-C42-023'], 'guide': 'Neuromuscular disorders combine spinal-cord/peripheral-nerve involvement with muscle weakness. SMA is autosomal recessive 5q SMN disease causing lower-motor-neuron hypotonia, atrophy and fasciculations while sparing extraocular muscles and mentation.'}, {'id': 'PEDS-U338', 'ch': 42, 'n': 2, 'title': 'SMA — Severity Types, Complications & Modern Therapy', 'sec': 'SMA types and management · p195', 'qs': ['PEDS-C42-024', 'PEDS-C42-025', 'PEDS-C42-026', 'PEDS-C42-027', 'PEDS-C42-028', 'PEDS-C42-029', 'PEDS-C42-030', 'PEDS-C42-031', 'PEDS-C42-032', 'PEDS-C42-033', 'PEDS-C42-034', 'PEDS-C42-035', 'PEDS-C42-036', 'PEDS-C42-037', 'PEDS-C42-038', 'PEDS-C42-039', 'PEDS-C42-040', 'PEDS-C42-041', 'PEDS-C42-042', 'PEDS-C42-043', 'PEDS-C42-044', 'PEDS-C42-045', 'PEDS-C42-046', 'PEDS-C42-047', 'PEDS-C42-048', 'PEDS-C42-049', 'PEDS-C42-050', 'PEDS-C42-051', 'PEDS-C42-052'], 'guide': 'SMA severity spans fatal prenatal type 0 through ambulant types 3–4. Swallowing-muscle hypotonia causes aspiration pneumonitis, a key mortality cause. Disease-modifying treatments restore SMN/exon-7 function but SMA is not classically curable.'}, {'id': 'PEDS-U339', 'ch': 42, 'n': 3, 'title': 'Duchenne Muscular Dystrophy — Basis & Early Features', 'sec': 'DMD pathology and early features · p195–196', 'qs': ['PEDS-C42-053', 'PEDS-C42-054', 'PEDS-C42-055', 'PEDS-C42-056', 'PEDS-C42-057', 'PEDS-C42-058', 'PEDS-C42-059', 'PEDS-C42-060', 'PEDS-C42-061', 'PEDS-C42-062', 'PEDS-C42-063', 'PEDS-C42-064', 'PEDS-C42-065', 'PEDS-C42-066', 'PEDS-C42-067', 'PEDS-C42-068', 'PEDS-C42-069', 'PEDS-C42-070', 'PEDS-C42-071', 'PEDS-C42-072', 'PEDS-C42-073', 'PEDS-C42-074', 'PEDS-C42-075'], 'guide': 'DMD is the commonest neuromuscular-dystrophy variant: X-linked recessive dystrophin loss destabilizes muscle, producing fiber death and fibrofatty replacement. Learn the early milestones, proximal weakness, Gower maneuver and calf pseudohypertrophy.'}, {'id': 'PEDS-U340', 'ch': 42, 'n': 4, 'title': 'Duchenne Muscular Dystrophy — Progression, Tests & Treatment', 'sec': 'DMD progression and treatment · p196', 'qs': ['PEDS-C42-076', 'PEDS-C42-077', 'PEDS-C42-078', 'PEDS-C42-079', 'PEDS-C42-080', 'PEDS-C42-081', 'PEDS-C42-082', 'PEDS-C42-083', 'PEDS-C42-084', 'PEDS-C42-085', 'PEDS-C42-086', 'PEDS-C42-087', 'PEDS-C42-088', 'PEDS-C42-089', 'PEDS-C42-090', 'PEDS-C42-091', 'PEDS-C42-092'], 'guide': 'DMD progression brings axial deformity, bulbar dysfunction and eventually cardiorespiratory death. Confirm with marked CK elevation/gene testing or biopsy; steroids slow apoptosis and targeted drugs address exon skipping or nonsense mutations.'}, {'id': 'PEDS-U341', 'ch': 42, 'n': 5, 'title': 'Becker, Facioscapulohumeral & Limb-Girdle Dystrophies', 'sec': 'Other muscular dystrophies · p197', 'qs': ['PEDS-C42-093', 'PEDS-C42-094', 'PEDS-C42-095', 'PEDS-C42-096', 'PEDS-C42-097', 'PEDS-C42-098', 'PEDS-C42-099', 'PEDS-C42-100', 'PEDS-C42-101', 'PEDS-C42-102', 'PEDS-C42-103', 'PEDS-C42-104', 'PEDS-C42-105', 'PEDS-C42-106', 'PEDS-C42-107', 'PEDS-C42-108', 'PEDS-C42-109', 'PEDS-C42-110', 'PEDS-C42-111', 'PEDS-C42-112', 'PEDS-C42-113', 'PEDS-C42-114', 'PEDS-C42-115', 'PEDS-C42-116'], 'guide': 'Becker is a milder dystrophin allelic variant with later onset but early cardiomyopathy. FSHD is autosomal dominant with facial, scapular and humeral weakness. Limb-girdle disease affects shoulder/hip girdles with preserved neck/bulbar muscle and normal IQ.'}, {'id': 'PEDS-U342', 'ch': 42, 'n': 6, 'title': 'Myotonic Dystrophy Type 1', 'sec': 'Myotonic dystrophy type 1 · p198', 'qs': ['PEDS-C42-117', 'PEDS-C42-118', 'PEDS-C42-119', 'PEDS-C42-120', 'PEDS-C42-121', 'PEDS-C42-122', 'PEDS-C42-123', 'PEDS-C42-124', 'PEDS-C42-125', 'PEDS-C42-126', 'PEDS-C42-127', 'PEDS-C42-128', 'PEDS-C42-129', 'PEDS-C42-130', 'PEDS-C42-131', 'PEDS-C42-132', 'PEDS-C42-133', 'PEDS-C42-134', 'PEDS-C42-135', 'PEDS-C42-136', 'PEDS-C42-137', 'PEDS-C42-138', 'PEDS-C42-139'], 'guide': 'Type 1 myotonic dystrophy is autosomal dominant DMPK disease from expanded CTG repeats. Recognize the hatchet face, delayed relaxation, distal weakness, cataract and endocrine associations.'}]
